<script setup>
import { onMounted,reactive,ref } from 'vue';import http from '../api/http';import { dateText } from '../utils/format'
const data=ref({records:[],total:0}),query=reactive({page:1,size:20});async function load(){data.value=await http.get('/api/notifications',{params:query})}async function read(item){if(item.isRead)return;await http.post(`/api/notifications/${item.id}/read`);item.isRead=true}onMounted(load)
</script>
<template><div><div class="page-head"><div><h1>消息中心</h1><p>任务申请、履约状态与系统治理通知</p></div></div><section class="surface panel"><article v-for="item in data.records" :key="item.id" class="list-card" :style="{background:item.isRead?'#f7f8f5':'#edf5ec',cursor:'pointer'}" @click="read(item)"><div style="display:flex;justify-content:space-between;gap:12px"><strong>{{item.title}} <el-badge v-if="!item.isRead" is-dot/></strong><span class="muted">{{dateText(item.createdAt)}}</span></div><p style="margin-bottom:0">{{item.content}}</p></article><div v-if="!data.records.length" class="empty">暂时没有新消息</div><div style="display:flex;justify-content:center"><el-pagination v-if="data.total>query.size" v-model:current-page="query.page" :page-size="query.size" :total="data.total" layout="prev,pager,next" @current-change="load"/></div></section></div></template>
